"""Single-camera, single-frame walk-up experience page."""

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Palmprint access demo</title><style>
*{box-sizing:border-box}body{margin:0;background:#101b27;color:#f4f8fc;font:18px system-ui,sans-serif}header{display:flex;justify-content:space-between;align-items:center;padding:20px 4vw}header a{color:#b8d7ef}main{max-width:1200px;margin:auto;padding:10px 4vw 30px;display:grid;grid-template-columns:1.4fr 1fr;gap:28px}.preview{position:relative;background:#050a10;border-radius:22px;overflow:hidden;aspect-ratio:16/9}.preview img{width:100%;height:100%;object-fit:contain}.guide{position:absolute;border:2px dashed #a5d8fa88;border-radius:35%;inset:12% 27%;pointer-events:none}.panel{display:flex;flex-direction:column;justify-content:center}#symbol{font-size:64px;color:#8dc8f3}h1{font-size:42px;margin:12px 0}#hint{font-size:21px;line-height:1.6;min-height:68px}.muted{font-size:14px;color:#abc0d3;line-height:1.7}button{font:inherit;border:1px solid #5e809e;border-radius:12px;padding:10px 22px;color:white;background:#213c54;cursor:pointer}.success #symbol,.success h1{color:#68e1b5}.retry #symbol,.retry h1{color:#ffd28b}#recent{font-size:14px;line-height:1.7;white-space:pre-wrap}.label{font-size:13px;letter-spacing:2px;color:#95b6d0}.timing{font-size:14px;line-height:1.8;color:#c2d4e4;min-height:65px}@media(max-width:800px){main{grid-template-columns:1fr}h1{font-size:32px}.panel{text-align:center}header{font-size:14px}}
</style></head><body><header><span>PALM PASS · Local demo</span><a href="/demo?mode=gate">Enrollment / Manage palms →</a></header>
<main><section><div class="preview"><img id="live" alt="Live camera preview"><div class="guide"></div></div><p id="camera" class="muted">Connecting to camera</p><p class="muted">Single camera · Single-frame identification · Demo test<br>Simulated access only. Recognition accuracy, anti-spoofing and real-device access performance have not been verified.</p><div id="recent" aria-label="Recent test results"></div></section>
<section class="panel" id="panel"><div class="label">Place palm · Identify · Remove palm</div><div id="symbol">◎</div><h1 id="title">Place your palm</h1><p id="hint" role="status" aria-live="polite">Face your palm toward the lens, keep the whole hand in view and hold briefly.</p><p id="timing" class="timing"></p><p id="users" class="muted">Loading enrollment information</p><div><button id="pause">Pause identification</button></div></section></main>
<script>
const $=id=>document.getElementById(id);
let paused=false,busy=false,armed=true,emptySince=null,userCount=null,needsCount=0,previewURL=null,retryFailures=0,retryNotBefore=0,recognitionEpoch=0;
const history=[];
function show(title,hint,kind='',symbol='◎'){$('title').textContent=title;$('hint').textContent=hint;$('panel').className='panel '+kind;$('symbol').textContent=symbol;}
async function request(url,options={},timeout=2500){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeout);try{const r=await fetch(url,{cache:'no-store',...options,signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.json();}finally{clearTimeout(timer);}}
async function users(){try{const d=await request('/api/demo/users');userCount=d.users.filter(u=>!u.needs_reenrollment).length;needsCount=d.users.filter(u=>u.needs_reenrollment).length;$('users').textContent=`Enrolled ${userCount} hands · Enroll each hand separately`+(needsCount?` · ${needsCount} hand records need review or updating`:'');}catch(e){$('users').textContent=userCount===null?'Enrollment information unavailable':`Enrollment information unavailable · Last read ${userCount} hands`; }setTimeout(users,5000);}
function decodePreview(url){return new Promise((resolve,reject)=>{const img=new Image();const finish=error=>{clearTimeout(timer);img.onload=null;img.onerror=null;error?reject(error):resolve()};const timer=setTimeout(()=>finish(Error('Preview image decoding timed out')),2500);img.onload=()=>finish();img.onerror=()=>finish(Error('Preview image decoding failed'));img.src=url;});}
async function preview(){let next;try{const r=await fetch('/debug/processed.jpg?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(2500)});if(!r.ok)throw Error();next=URL.createObjectURL(await r.blob());await decodePreview(next);$('live').src=next;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=next;next=null;}catch(e){$('live').removeAttribute('src');}finally{if(next)URL.revokeObjectURL(next);setTimeout(preview,150);}}
async function identify(){const epoch=recognitionEpoch;busy=true;armed=false;emptySince=null;$('timing').textContent='';show('Identifying','Hold your hand steady while one frame is captured and identified.');const started=performance.now();try{const d=await request('/api/gate/identify',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'},20000);if(epoch!==recognitionEpoch)return;const elapsed=performance.now()-started;const t=d.timing_ms||{};let message;if(d.status==='MATCH'){retryFailures=0;retryNotBefore=0;message=`Simulated access granted · ${d.display_name}`;show('Simulated access granted',`${d.display_name}, remove your hand.`,'success','✓');}else if(d.status==='UNKNOWN'){retryFailures=0;retryNotBefore=0;if(d.reason==='NO_ENROLLED_USERS'){message='No usable enrollment records';show('Check enrollment records','No enrollment records available for identification. Open enrollment management to check, then remove your hand before retrying.','retry','!');}else{message='No enrolled palm recognized';show('Not recognized','Remove your hand and retry. First-time users should enroll first.','retry','○');}}else{message='Retry needed';if(['GALLERY_INCOMPATIBLE_TEMPLATES','INCOMPATIBLE_TEMPLATES'].includes(d.reason)){message='Enrollment records need updating';show('Update enrollment records','Open enrollment management and re-enroll with the original ID. The existing balance is retained.','retry','!');}else if(['GALLERY_INCOMPLETE_TEMPLATES','GALLERY_INVALID_TEMPLATES','GALLERY_ACCOUNT_MISMATCH'].includes(d.reason)){message='Enrollment records need review';show('Check enrollment records','Enrollment records are incomplete or inconsistent with the account. Open enrollment management to check.','retry','!');}else if(d.reason==='GALLERY_CHANGED_DURING_QUERY'){message='Enrollment records are changing';show('Enrollment records are changing','Wait for the update to finish. Remove your hand and retry.','retry','↻');}else if(['NO_HAND','ROI_UNSTABLE','ROI_NOT_READY','ROI_GEOMETRY_INVALID','CAPTURE_TIMEOUT','INSUFFICIENT_QUALITY_FRAMES','CAMERA_BUSY','CAMERA_UNAVAILABLE'].includes(d.reason)){armed=true;retryFailures++;retryNotBefore=performance.now()+Math.min(1000*2**Math.min(retryFailures-1,3),8000);show('Adjust your palm','Capture resumes automatically once the palm is stable.','retry','↻');}else show('Try again','Remove your hand, adjust distance and pose, then retry.','retry','↻');}$('timing').textContent=`This request ${(elapsed/1000).toFixed(2)} s`+(Number.isFinite(t.capture_and_extract)?` · Capture and features ${(t.capture_and_extract/1000).toFixed(2)} s`:'')+(Number.isFinite(t.gallery)?` · Gallery matching ${(t.gallery/1000).toFixed(2)} s`:'');history.unshift(`${new Date().toLocaleTimeString()}  ${message}  ${(elapsed/1000).toFixed(2)}s`);$('recent').textContent=history.slice(0,6).join('\n');}catch(e){if(epoch===recognitionEpoch)show('Connection or processing error','Remove your hand and retry.','retry','!');}finally{busy=false;}}
async function poll(){try{const d=await request('/api/status?t='+Date.now());const state=d.demo_quality_status??d.quality_status;const count=Number(d.demo_quality_consecutive_frames??d.quality_consecutive_frames??0);const required=Number(d.demo_quality_required_frames??d.quality_required_frames??5);const fresh=d.camera_ready&&d.roi_status_fresh===true;$('camera').textContent=fresh?'Camera connected · Live palm detection':'Camera or palm status unavailable';if(!busy&&!document.hidden){if(paused){show('Identification paused','Click Continue to start the next round.');}else if(userCount===null){show('Enrollment information unavailable','Waiting for enrollment information to recover.','retry');}else if(userCount===0){if(needsCount)show('Check enrollment records','Open enrollment management to check and update records using the original ID.','retry','!');else show('Enroll your palm first','Use the enrollment link at the top right to capture and save five frames automatically.');}else if(!fresh){emptySince=null;show('Waiting for camera','Waiting for the live feed and detection status to recover.','retry');}else if(!armed){if(state==='NO_HAND'){emptySince??=performance.now();if(performance.now()-emptySince>=700){armed=true;emptySince=null;$('timing').textContent='';show('Place your palm','Face your palm toward the lens, keep the whole hand in view and hold briefly.');}}else emptySince=null;}else if(state==='READY'&&count>=required){if(performance.now()>=retryNotBefore)void identify();else show('Adjust your palm','Waiting for palm stability before retrying automatically.','retry','↻');}else if(state==='NO_HAND'){retryFailures=0;retryNotBefore=0;show('Place your palm','Face your palm toward the lens, keep the whole hand in view and hold briefly.');}else{show('Hold your hand steady','Face the palm toward the lens, adjust the distance slightly and wait for a clear, stable frame.');}}}catch(e){emptySince=null;if(!busy)show('Connection unavailable','Waiting for service recovery.','retry');}finally{setTimeout(poll,300);}}
$('pause').onclick=()=>{recognitionEpoch++;paused=!paused;$('pause').textContent=paused?'Continue identification':'Pause identification';if(paused){show('Identification paused','Click Continue to start the next round.');}else{armed=false;emptySince=null;show('Remove your palm','Remove and replace your hand to start the next round.');}};
users();preview();poll();
</script></body></html>'''
